-- ============================================================================
-- 054_arith_partnership.sql
-- Question-bank seed: Arithmetic chapter "Partnership" -- 36 single-answer MCQs
-- from ACTUAL previous-year papers (SBI/IBPS/RBI/Canara PO & Clerk, SSC CGL/CHSL,
-- TS/AP ICET, TCS NQT/Infosys/Wipro/Cognizant) via IndiaBix, PrepInsta, Testbook,
-- Adda247, Oliveboard, CareerPower, Examveda, 2IIM, GeeksforGeeks, Sawaal.
-- Capital ratio, capital x time, join/leave midway, working-partner salary/commission.
-- Exam-grade difficulty floor; answers independently recomputed & each correct option
-- re-derived (not trusting the source index); 4 distinct-valued options, one correct;
-- each carries a worked explanation. Depends on 023. Reuses the idempotent
-- _seed_arith_q helper (dollar-quoted). Safe to re-run.
-- ============================================================================

create or replace function public._seed_arith_q(p_chapter text, p_difficulty text, p_stem text, p_opts text[], p_correct int, p_explanation text) returns void language plpgsql as $$
declare v_subj uuid; v_chap uuid; v_qid uuid; i int;
begin
  select id into v_subj from public.subject where lower(name)='arithmetic' limit 1;
  if v_subj is null then raise exception 'Arithmetic subject not found (run 023 first)'; end if;
  select id into v_chap from public.chapter where subject_id=v_subj and lower(name)=lower(p_chapter) limit 1;
  if v_chap is null then raise exception 'Chapter % not found', p_chapter; end if;
  if exists (select 1 from public.question where chapter_id=v_chap and stem=p_stem) then return; end if;
  insert into public.question (subject_id, chapter_id, kind, difficulty, answer_type, stem, explanation)
  values (v_subj, v_chap, 'standard', p_difficulty, 'single', p_stem, p_explanation) returning id into v_qid;
  for i in 1..array_length(p_opts,1) loop
    insert into public.question_option (question_id, label, is_correct, position) values (v_qid, p_opts[i], i=p_correct, i-1);
  end loop;
end; $$;

-- Partnership (36 questions)
select public._seed_arith_q($q$Partnership$q$,'easy',$q$A and B start a business investing ₹5,000 and ₹6,000 respectively. At year end the profit is ₹3,300. Find A's share.$q$,array[$q$₹1,500$q$,$q$₹1,800$q$,$q$₹1,650$q$,$q$₹1,320$q$],1,$q$Ratio 5000:6000 = 5:6, total 11 parts. A = 3300×5/11 = ₹1,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$P and Q invest ₹8,000 and ₹12,000 in a firm. If the total profit is ₹5,000, what is Q's share?$q$,array[$q$₹2,000$q$,$q$₹3,000$q$,$q$₹2,500$q$,$q$₹3,200$q$],2,$q$Ratio 8:12 = 2:3, total 5. Q = 5000×3/5 = ₹3,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$Two friends divide a profit in the ratio 4:5. If the total profit is ₹4,500, find the smaller share.$q$,array[$q$₹2,500$q$,$q$₹1,800$q$,$q$₹2,000$q$,$q$₹2,250$q$],3,$q$Total 9 parts; smaller = 4500×4/9 = ₹2,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$A invests ₹7,500 and B invests ₹4,500. At the end of the year the profit is ₹4,000. Find A's share.$q$,array[$q$₹2,500$q$,$q$₹1,500$q$,$q$₹2,000$q$,$q$₹2,800$q$],1,$q$Ratio 7500:4500 = 5:3, total 8. A = 4000×5/8 = ₹2,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$A and B share profit in the ratio 3:2. If B receives ₹8,000, what was the total profit?$q$,array[$q$₹16,000$q$,$q$₹20,000$q$,$q$₹18,000$q$,$q$₹12,000$q$],2,$q$B's 2 parts = 8000, so 1 part = 4000; total 5 parts = ₹20,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$P puts in ₹12,000 and Q puts in ₹16,000. If the year's profit is ₹7,000, find P's share.$q$,array[$q$₹4,000$q$,$q$₹3,500$q$,$q$₹3,000$q$,$q$₹2,800$q$],3,$q$Ratio 12:16 = 3:4, total 7. P = 7000×3/7 = ₹3,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$Two partners invest capital in the ratio 2:3 and share the ₹15,000 profit accordingly. By how much does the larger share exceed the smaller?$q$,array[$q$₹3,000$q$,$q$₹5,000$q$,$q$₹6,000$q$,$q$₹9,000$q$],1,$q$Shares: 15000×2/5=6000, 15000×3/5=9000; difference = ₹3,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$A and B invest ₹6,400 and ₹8,000. If the profit at year end is ₹2,700, find B's share.$q$,array[$q$₹1,200$q$,$q$₹1,500$q$,$q$₹1,350$q$,$q$₹1,600$q$],2,$q$Ratio 6400:8000 = 4:5, total 9. B = 2700×5/9 = ₹1,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'easy',$q$A invests ₹9,000 and B invests ₹6,000 for the same period. The profit is ₹2,500. Find A's share.$q$,array[$q$₹1,000$q$,$q$₹1,250$q$,$q$₹1,500$q$,$q$₹1,800$q$],3,$q$Ratio 9:6 = 3:2, total 5. A = 2500×3/5 = ₹1,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$A, B and C invest capitals in the ratio 3:4:5 in a business. If the total profit is ₹24,000, find C's share.$q$,array[$q$₹6,000$q$,$q$₹8,000$q$,$q$₹10,000$q$,$q$₹12,000$q$],3,$q$Total 12 parts; C = 24000×5/12 = ₹10,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$A, B and C invest ₹20,000, ₹15,000 and ₹25,000 respectively. If the total profit is ₹12,000, find B's share.$q$,array[$q$₹4,000$q$,$q$₹3,000$q$,$q$₹5,000$q$,$q$₹2,500$q$],2,$q$Ratio 20:15:25 = 4:3:5, total 12. B = 12000×3/12 = ₹3,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$A invests ₹5,000 for 12 months. B invests ₹6,000 and, at year end, both receive equal profit shares. For how many months was B's capital invested?$q$,array[$q$8 months$q$,$q$9 months$q$,$q$10 months$q$,$q$12 months$q$],3,$q$Equal shares ⇒ 5000×12 = 6000×t ⇒ t = 60000/6000 = 10 months.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$Three partners share profit in the ratio 2:3:5. The largest share exceeds the smallest by ₹6,000. Find the total profit.$q$,array[$q$₹18,000$q$,$q$₹20,000$q$,$q$₹24,000$q$,$q$₹15,000$q$],2,$q$Difference = (5−2) = 3 parts = 6000 ⇒ 1 part = 2000; total 10 parts = ₹20,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$Partners A, B, C invest in the ratio 4:5:6. If B's share of the profit is ₹7,500, what is the total profit?$q$,array[$q$₹18,000$q$,$q$₹20,000$q$,$q$₹22,500$q$,$q$₹24,000$q$],3,$q$B's 5 parts = 7500 ⇒ 1 part = 1500; total 15 parts = ₹22,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$A invests three times as much as B, and B invests twice as much as C. If the total profit is ₹63,000, find C's share.$q$,array[$q$₹6,000$q$,$q$₹7,000$q$,$q$₹9,000$q$,$q$₹14,000$q$],2,$q$C=1, B=2, A=6 ⇒ ratio 6:2:1, total 9. C = 63000×1/9 = ₹7,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$The profit of ₹8,400 is divided among A, B and C in the ratio 7:5:3. Find A's share.$q$,array[$q$₹2,800$q$,$q$₹3,920$q$,$q$₹1,680$q$,$q$₹3,500$q$],2,$q$Total 15 parts; A = 8400×7/15 = ₹3,920.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$A, B and C invest in the ratio 1/2 : 1/3 : 1/4. If the total profit is ₹5,200, find A's share.$q$,array[$q$₹2,400$q$,$q$₹1,600$q$,$q$₹1,200$q$,$q$₹2,000$q$],1,$q$LCM-clear: 6:4:3, total 13. A = 5200×6/13 = ₹2,400.$q$);
select public._seed_arith_q($q$Partnership$q$,'medium',$q$P and Q invest equal capitals. P remains in the business for 12 months but Q joins later and stays only 8 months. If the profit is ₹5,000, find P's share.$q$,array[$q$₹2,500$q$,$q$₹2,000$q$,$q$₹3,000$q$,$q$₹3,200$q$],3,$q$Capital equal ⇒ ratio of time 12:8 = 3:2, total 5. P = 5000×3/5 = ₹3,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A invests ₹4,000 for 12 months and B invests ₹6,000 for 6 months. If the total profit is ₹7,000, find A's share.$q$,array[$q$₹3,000$q$,$q$₹4,000$q$,$q$₹3,500$q$,$q$₹4,500$q$],2,$q$Capital×time: 4000×12=48000, 6000×6=36000 ⇒ 4:3, total 7. A = 7000×4/7 = ₹4,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A puts in ₹8,000 for 6 months while B puts in ₹4,000 for the full 12 months. The total profit is ₹9,000. Find B's share.$q$,array[$q$₹6,000$q$,$q$₹4,000$q$,$q$₹4,500$q$,$q$₹5,000$q$],3,$q$48000:48000 = 1:1 ⇒ each gets 9000/2 = ₹4,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A starts a business with ₹20,000. B joins after 4 months with ₹30,000. At the end of the year the profit is ₹10,000. Find B's share.$q$,array[$q$₹4,000$q$,$q$₹5,000$q$,$q$₹6,000$q$,$q$₹4,500$q$],2,$q$A=20000×12=240000, B=30000×8=240000 ⇒ 1:1. B = 10000/2 = ₹5,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A invests ₹15,000. Three months later B joins with ₹20,000. At year end (A for 12 months, B for 9) the profit is ₹4,500. Find B's share.$q$,array[$q$₹2,250$q$,$q$₹2,000$q$,$q$₹2,500$q$,$q$₹3,000$q$],1,$q$A=15000×12=180000, B=20000×9=180000 ⇒ 1:1. B = 4500/2 = ₹2,250.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A and B invest ₹5,000 and ₹6,000. A, the working partner, gets 10% of the profit for managing, and the rest is shared in the capital ratio. If the total profit is ₹8,800, find A's total share.$q$,array[$q$₹4,000$q$,$q$₹4,480$q$,$q$₹4,320$q$,$q$₹3,600$q$],2,$q$Commission 10% = 880; remaining 7920 in 5:6 ⇒ A = 7920×5/11 = 3600; total = 3600+880 = ₹4,480.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A, B and C invest ₹5,000, ₹6,000 and ₹9,000. C is the working partner and takes ₹3,000 as salary; the rest of the ₹33,000 profit is shared in the capital ratio. Find C's total share.$q$,array[$q$₹13,500$q$,$q$₹16,500$q$,$q$₹15,000$q$,$q$₹14,000$q$],2,$q$Remaining = 30000; ratio 5:6:9 (sum 20) ⇒ C = 30000×9/20 = 13500; total = 13500+3000 = ₹16,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A invests ₹40,000 for the full year. B joins after 2 months with ₹60,000. If the total profit is ₹9,000, find A's share.$q$,array[$q$₹5,000$q$,$q$₹4,000$q$,$q$₹4,500$q$,$q$₹3,600$q$],2,$q$A=40000×12=480000, B=60000×10=600000 ⇒ 4:5, total 9. A = 9000×4/9 = ₹4,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A, B and C invest ₹12,000, ₹8,000 and ₹6,000 for 12, 6 and 4 months respectively. If the total profit is ₹18,000, find A's share.$q$,array[$q$₹9,000$q$,$q$₹12,000$q$,$q$₹6,000$q$,$q$₹10,000$q$],2,$q$Cap×time: 144000:48000:24000 = 6:2:1, total 9. A = 18000×6/9 = ₹12,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'hard',$q$A invests ₹5,000 for the whole year. B joins after 4 months with ₹6,000. If the total profit is ₹9,000, find A's share.$q$,array[$q$₹4,000$q$,$q$₹5,000$q$,$q$₹4,500$q$,$q$₹5,500$q$],2,$q$A=5000×12=60000, B=6000×8=48000 ⇒ 5:4, total 9. A = 9000×5/9 = ₹5,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A starts with ₹8,000 but withdraws ₹2,000 after 6 months. B invests ₹6,000 for the whole year. If the total profit is ₹13,000, find A's share.$q$,array[$q$₹6,000$q$,$q$₹7,000$q$,$q$₹6,500$q$,$q$₹7,500$q$],2,$q$A=8000×6+6000×6=84000, B=6000×12=72000 ⇒ 7:6, total 13. A = 13000×7/13 = ₹7,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A invests ₹10,000 and adds ₹5,000 more after 8 months. B invests ₹15,000 for the whole year. If the total profit is ₹8,000, find A's share.$q$,array[$q$₹4,000$q$,$q$₹3,500$q$,$q$₹4,500$q$,$q$₹3,000$q$],2,$q$A=10000×12+5000×4=140000, B=15000×12=180000 ⇒ 7:9, total 16. A = 8000×7/16 = ₹3,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A firm's manager is paid 5% of the profit as commission, and the remainder is shared between A and B in the ratio 3:4. If the total profit is ₹42,000, find A's share.$q$,array[$q$₹17,100$q$,$q$₹18,000$q$,$q$₹16,000$q$,$q$₹15,750$q$],1,$q$Commission = 5% of 42000 = 2100; remaining 39900 in 3:4 (sum 7) ⇒ A = 39900×3/7 = ₹17,100.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A and B share profit in the ratio 2:3. A's capital was invested for 12 months and B's for 9 months. Find the ratio of their capitals.$q$,array[$q$1 : 2$q$,$q$2 : 3$q$,$q$3 : 4$q$,$q$1 : 3$q$],1,$q$Capital = profit/time: A:B = (2/12):(3/9) = (1/6):(1/3) = 1:2.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A invests ₹6,000 for the whole year. B joins after 3 months with ₹8,000 and C joins after 6 months with ₹10,000. If the total profit is ₹51,000, find C's share.$q$,array[$q$₹18,000$q$,$q$₹15,000$q$,$q$₹12,000$q$,$q$₹16,000$q$],2,$q$Cap×time: 72000:72000:60000 = 6:6:5, total 17. C = 51000×5/17 = ₹15,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A invests ₹12,000 but reduces it to ₹9,000 after 4 months. B invests ₹10,000 for the full year. If the total profit is ₹14,000, find A's share.$q$,array[$q$₹7,000$q$,$q$₹8,000$q$,$q$₹6,000$q$,$q$₹7,500$q$],1,$q$A=12000×4+9000×8=120000, B=10000×12=120000 ⇒ 1:1. A = 14000/2 = ₹7,000.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$In a partnership, the working partner A takes 1/10 of the profit for managing and the balance is shared between A and B in the capital ratio 3:5. If the total profit is ₹8,000, find A's total share.$q$,array[$q$₹3,500$q$,$q$₹2,700$q$,$q$₹4,000$q$,$q$₹3,000$q$],1,$q$Commission = 1/10×8000 = 800; balance 7200 in 3:5 (sum 8) ⇒ A = 7200×3/8 = 2700; total = 2700+800 = ₹3,500.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A, B and C receive profit in the ratio 5:3:12 for investment periods of 5, 3 and 6 months respectively. Find the ratio of their capitals.$q$,array[$q$1 : 1 : 2$q$,$q$1 : 2 : 3$q$,$q$2 : 1 : 3$q$,$q$1 : 1 : 3$q$],1,$q$Capital = profit/time: 5/5 : 3/3 : 12/6 = 1 : 1 : 2.$q$);
select public._seed_arith_q($q$Partnership$q$,'very_hard',$q$A starts with ₹30,000. After 6 months B joins with ₹45,000, and after 8 months C joins with ₹60,000. If the year's profit is ₹29,000, find A's share.$q$,array[$q$₹9,000$q$,$q$₹12,000$q$,$q$₹8,000$q$,$q$₹10,800$q$],2,$q$Cap×time: 30000×12=360000, 45000×6=270000, 60000×4=240000 ⇒ 12:9:8, total 29. A = 29000×12/29 = ₹12,000.$q$);

drop function public._seed_arith_q(text,text,text,text[],int,text);
